static const char upper_map[128]={[0x02]='!',[0x03]='@',[0x04]='#',[0x05]='$',[0x06]='%',[0x07]='^',[0x08]='&',[0x09]='*',[0x0A]='(',[0x0B]=')',[0x0C]='_',[0x0D]='+',[0x10]='Q',[0x11]='W',[0x12]='E',[0x13]='R',[0x14]='T',[0x15]='Y',[0x16]='U',[0x17]='I',[0x18]='O',[0x19]='P',[0x1A]='{',[0x1B]='}',[0x1E]='A',[0x1F]='S',[0x20]='D',[0x21]='F',[0x22]='G',[0x23]='H',[0x24]='J',[0x25]='K',[0x26]='L',[0x27]=':',[0x28]='"',[0x29]='~',[0x2B]='|',[0x2C]='Z',[0x2D]='X',[0x2E]='C',[0x2F]='V',[0x30]='B',[0x31]='N',[0x32]='M',[0x33]='<',[0x34]='>',[0x35]='?',[0x39]=' '};
static int wait_in(void){for(u32 i=0;i<100000;i++)if(!(inb(0x64)&2))return 1;return 0;}
static int wait_out(void){for(u32 i=0;i<100000;i++)if(inb(0x64)&1)return 1;return 0;}
void keyboard_init(void){
    for(int i=0;i<64;i++){u8 st=inb(0x64);if(!(st&1))break;(void)inb(0x60);}
    if(wait_in())outb(0x64,0xAE);
    if(wait_in())outb(0x64,0x20);
    u8 c=wait_out()?inb(0x60):0x40;
    c|=0x40;
    c&=(u8)~0x10;
    if(wait_in())outb(0x64,0x60);
    if(wait_in())outb(0x60,c);
    if(wait_in())outb(0x60,0xF4);
    if(wait_out())(void)inb(0x60);
}
KeyEvent keyboard_poll(void){static u8 shift=0,ctrl=0,alt=0,ext=0;KeyEvent e={0,0,KEY_NONE,ctrl,alt,shift};u8 st=inb(0x64);if(!(st&1))return e;if(st&0x20){if(!mouse_available())(void)inb(0x60);return e;}u8 s=inb(0x60);if(s==0xE0){ext=1;return e;}if(s==0x2A||s==0x36){shift=1;return e;}if(s==0xAA||s==0xB6){shift=0;return e;}if(s==0x1D){ctrl=1;return e;}if(s==0x9D){ctrl=0;return e;}if(s==0x38){alt=1;return e;}if(s==0xB8){alt=0;return e;}if(s&0x80){ext=0;return e;}e.pressed=1;e.ctrl=ctrl;e.alt=alt;e.shift=shift;if(ext){if(s==0x48)e.special=KEY_UP;else if(s==0x50)e.special=KEY_DOWN;else if(s==0x4B)e.special=KEY_LEFT;else if(s==0x4D)e.special=KEY_RIGHT;ext=0;return e;}if(s==0x1C)e.special=KEY_ENTER;else if(s==0x0E)e.special=KEY_BACKSPACE;else if(s==0x0F)e.special=KEY_TAB;else if(s==0x01)e.special=KEY_ESC;else if(s>=0x3B&&s<=0x44)e.special=(u8)(KEY_F1+(s-0x3B));else if(s==0x57)e.special=KEY_F11;else if(s==0x58)e.special=KEY_F12;else e.ch=shift?upper_map[s]:lower_map[s];return e;}
